var FlipPriceRanges = (() => {
  const levels=[{key:'top',min:90,label:'Top Flip',points:'Ab 90 Punkte',tone:'range-good'},{key:'good',min:80,label:'Für den Preis ein guter Flip',points:'80 bis unter 90 Punkte',tone:'range-good'},{key:'borderline',min:70,label:'Grenzfall, genau prüfen',points:'70 bis unter 80 Punkte',tone:'range-mid'},{key:'weak',min:60,label:'Kein Deal',points:'60 bis unter 70 Punkte',tone:'range-bad'},{key:'reject',min:0,label:'Kein Flip / Finger weg',points:'Unter 60 Punkte',tone:'range-bad'}];
  function evaluate(purchase,inputs){const cost=purchase*inputs.costRate+inputs.fixedCost,lowProfit=(inputs.lowSale-cost-inputs.saleBroker*inputs.lowSale-inputs.staging)*(1-inputs.coinvest),highProfit=(inputs.highSale-cost-inputs.saleBroker*inputs.highSale-inputs.staging)*(1-inputs.coinvest),margin=cost>0?(lowProfit+highProfit)/2/cost:null,marginPoints=margin===null?0:margin>=.25?25:margin>=.2?20:margin>=.15?12.5:0,perSqm=purchase/inputs.area,pricePoints=perSqm<=inputs.averageSqm?8:perSqm<=inputs.averageSqm*1.2?5.5:perSqm<=inputs.averageSqm*1.35?3:perSqm<=inputs.averageSqm*1.5?1.5:0;const points=inputs.fixedPoints+marginPoints+pricePoints;return {points,margin,key:levels.find(level=>points>=level.min).key}}
  function ranges(inputs){if(inputs.excluded)return {status:'excluded',levels};const numeric=['area','averageSqm','lowSale','highSale','costRate','fixedCost','saleBroker','staging','coinvest','fixedPoints','purchase'];if(!inputs.complete||numeric.some(key=>!Number.isFinite(inputs[key]))||inputs.area<=0||inputs.averageSqm<0||inputs.purchase<0||inputs.costRate<=0||inputs.fixedCost<=0||inputs.saleBroker<0||inputs.saleBroker>1||inputs.staging<0||inputs.coinvest<0||inputs.coinvest>1)return {status:'incomplete',levels};const cap=Number.MAX_SAFE_INTEGER/4,score=cents=>evaluate(cents/100,inputs).points;function highest(min){if(inputs.fixedPoints>=min)return Infinity;if(score(0)<min)return null;let high=Math.max(100,Math.ceil(Math.max(0,inputs.purchase)*100));if(high>cap)return undefined;while(score(high)>=min){if(high>cap/2)return undefined;high*=2}let low=0;while(low+1<high){const middle=low+Math.floor((high-low)/2);if(score(middle)>=min)low=middle;else high=middle}return low}let previous=null;const result=[];for(const level of levels){let upper=level.min===0?Infinity:highest(level.min);if(upper===undefined)return {status:'unavailable',levels};const lower=previous===null?0:previous===Infinity?Infinity:previous+1;const reachable=upper!==null&&lower!==Infinity&&lower<=upper;result.push({...level,reachable,from:reachable?lower/100:null,to:reachable?(upper===Infinity?Infinity:upper/100):null});if(upper!==null)previous=upper}return {status:'ok',levels:result,fixedPoints:inputs.fixedPoints}}
  function markup(inputs){const result=ranges(inputs),money=value=>new Intl.NumberFormat('de-DE',{style:'currency',currency:'EUR',minimumFractionDigits:2,maximumFractionDigits:2}).format(value);let intro='';if(result.status==='excluded')intro='<p class="price-range-alert">Ausschluss bei jedem Kaufpreis: Elektroheizung oder Sonderumlage über 10.000 €. Ein niedrigerer Preis hebt dieses Ausschlusskriterium nicht auf.</p>';else if(result.status==='incomplete')intro='<p class="hint">Für konkrete Kaufpreisbereiche bitte die Kalkulation und alle Angaben für das Punktesystem vervollständigen.</p>';else if(result.status==='unavailable')intro='<p class="hint">Die Preisgrenzen liegen außerhalb des zuverlässig berechenbaren Zahlenbereichs.</p>';else intro='<p class="hint">'+new Intl.NumberFormat('de-DE').format(result.fixedPoints)+' Punkte stammen aus den kaufpreisunabhängigen Objektmerkmalen. Nur die Punkte für Kaufpreis und Marge ändern sich in dieser Übersicht.</p>';const rows=result.levels.map(level=>{let range=result.status==='excluded'?'Ausschluss unabhängig vom Preis':result.status!=='ok'?'Noch nicht berechenbar':!level.reachable?'Mit diesen Annahmen nicht erreichbar':level.from===0&&level.to!==Infinity?'Bis '+money(level.to):level.to===Infinity?'Ab '+money(level.from):money(level.from)+' bis '+money(level.to);const current=result.status==='ok'&&level.reachable&&inputs.purchase>=level.from&&(level.to===Infinity||inputs.purchase<=level.to);return `<tr class="${level.tone}${current?' is-current-range':''}"><td>${level.label}${current?' · aktuell':''}</td><td>${level.points}</td><td>${range}</td></tr>`}).join('');return intro+'<div class="wide"><table class="price-range-table"><thead><tr><th>Bewertung</th><th>Punkteschwelle</th><th>Kaufpreisbereich für dieses Objekt</th></tr></thead><tbody>'+rows+'</tbody></table></div>'}
  return {levels,evaluate,ranges,markup};
})();
if(typeof module!=='undefined'&&module.exports)module.exports=FlipPriceRanges;
